import type { BridgeMessagePayload } from "@notionhq/custom-blocks-protocol"
import type { PrimeableHostToSandboxMessage } from "@notionhq/custom-blocks-protocol/messages/hostToSandbox.js"

/**
 * Shared across sandbox bridge instances. Each result type holds one response;
 * consuming it removes it, and priming it again replaces the previous response.
 */
export const globalPrimedResponsesCache = new Map<
	PrimeableHostToSandboxMessage["type"],
	BridgeMessagePayload<PrimeableHostToSandboxMessage>
>()
